const context = $('Build Direct RAG Test Context').item.json;
const allowed = new Set(["general_information","how_it_works","food_decision","food_context","recommendation_feedback","price","delivery_channel","glp1_scope","medical_boundary","purchase_intent","acknowledgement","unsupported"]);
try { const raw = String($input.first().json.output || '').replace(/^\x60\x60\x60(?:json)?\s*|\s*\x60\x60\x60$/g, ''); const parsed = JSON.parse(raw); const obligations = parsed.obligations;
  if (!Array.isArray(obligations) || !obligations.length || obligations.length > 8) throw new Error('count');
  const normalized = []; const seen = new Set();
  for (const o of obligations) {
    if (!o || !allowed.has(o.type) || typeof o.evidence !== 'string' || !context.current_message.includes(o.evidence)) continue;
    const key = JSON.stringify([o.type, o.evidence]);
    if (seen.has(key)) continue;
    seen.add(key); normalized.push({ id: 'o-' + (normalized.length + 1), type: o.type, evidence: o.evidence });
  }
  return [{ json: { ...context, obligations: normalized.length ? normalized : [{ id: 'o-1', type: 'unsupported', evidence: context.current_message }] } }];
} catch { return [{ json: { ...context, obligations: [{ id: 'o-1', type: 'unsupported', evidence: context.current_message }] } }]; }

const input = $input.first().json;
function extractFoodContext(message, mostRecentAssistantMessage = '') {
  const text = String(message || '').normalize('NFD').replace(/[\u0300-\u036f]/gu, '').toLowerCase();
  const foodTerms = [
    ['huevos', /\bhuevos?\b/u], ['pollo', /\bpollo\b/u], ['tortillas', /\btortillas?\b/u],
    ['aguacate', /\baguacate\b/u], ['pechuga', /\bpechuga\b/u],
    ['verduras', /\b(?:vegetales|verduras?)\b/u], ['arroz', /\barroz\b/u],
    ['pescado', /\bpescado\b/u], ['carne', /\bcarne\b/u], ['leche', /\bleche\b/u],
    ['fruta', /\bfrutas?\b/u], ['tocino', /\btocino\b/u], ['cafe', /\bcafe\b/u],
  ];
  const foods = value => foodTerms.filter(([, pattern]) => pattern.test(value)).map(([food]) => food);
  const contextual_rejection = /\bno se me antoja|no quiero|no me apetece\b/u.test(text);
  const explicitConsumed = /\b(?:ya\s+)?(?:me\s+)?(?:comi|desayune|cene|almorce|merende)\b/u.test(text)
    || /\b(?:para|de)\s+(?:el\s+|la\s+)?(?:desayuno|desayunar|comida|comer|cena|cenar)\b/u.test(text)
    || /\bmi\s+(?:desayuno|comida|cena)\b/u.test(text);
  const availableMatch = text.match(/\b(?:tengo(?:\s+disponibles?)?|hay|cuento\s+con|dispongo\s+de)\s+([^.!?]+)/u);
  const explicitlyAvailable = availableMatch ? foods(availableMatch[1]) : [];
  const explicitlyConsumed = explicitConsumed ? foods(text.split(/\bpero\b/u)[0]) : [];
  const recentQuestion = String(mostRecentAssistantMessage || '').normalize('NFD').replace(/[\u0300-\u036f]/gu, '').toLowerCase();
  const askedForAvailability = /(?:que|cuales?)\s+(?:alimentos|comida|ingredientes)[^?]{0,100}(?:tienes|hay|disponibles?)/u.test(recentQuestion);
  const bareFoods = foods(text);
  const inferredAvailable = explicitlyConsumed.length === 0 && explicitlyAvailable.length === 0
    && !contextual_rejection && askedForAvailability && !/[?¿]/u.test(text) ? bareFoods : [];
  return {
    recently_consumed: explicitlyConsumed,
    available_foods: explicitlyAvailable.length ? explicitlyAvailable : inferredAvailable,
    appetite: /\bpoco apetito|no tengo hambre|poca hambre\b/u.test(text) ? 'low' : null,
    contextual_rejection,
  };
}
function resolveFoodDecision(message, mostRecentAssistantMessage = '', history = []) {
  const context = extractFoodContext(message, mostRecentAssistantMessage);
  const has = food => context.available_foods.includes(food);
  if (has('huevos') && has('tortillas') && has('aguacate')) return { context, permitted_claims: ['Puedes comer 2 huevos revueltos con una tortilla y un poco de aguacate. Es una porción sencilla si tienes poco apetito.'], clarification_question: null };
  if (has('pollo') && has('tortillas') && has('aguacate')) return { context, permitted_claims: ['Puedes preparar una tortilla con pollo y un poco de aguacate. Usa una porción sencilla y come despacio si todavía tienes poco apetito.'], clarification_question: null };
  if (context.available_foods.length) {
    const lastCustomer = Array.isArray(history) ? [...history].reverse().find(item => item?.role === 'customer') : null;
    const lastCustomerText = String(lastCustomer?.text || '').normalize('NFD').replace(/[\u0300-\u036f]/gu, '').toLowerCase();
    const lowAppetite = context.appetite === 'low' || /\bpoco apetito|no tengo hambre|poca hambre\b/u.test(lastCustomerText);
    const protein = ['huevos', 'pollo', 'pechuga', 'pescado', 'carne', 'tocino'].find(has);
    const vegetable = has('verduras') ? 'verduras' : null;
    const starch = has('arroz') ? 'arroz' : has('tortillas') ? 'tortilla' : null;
    let meal;
    if (protein) meal = [protein, vegetable ? `con ${vegetable}` : null, !vegetable && starch ? `con ${starch}` : null].filter(Boolean).join(' ');
    else if (vegetable && starch) meal = `${starch} con ${vegetable}`;
    else if (has('leche') && has('fruta')) meal = 'leche con fruta';
    else meal = context.available_foods[0];
    const appetiteNote = lowAppetite ? ' Empieza con una porción pequeña y come despacio.' : '';
    return { context, permitted_claims: [`Con lo que tienes, prepara ${meal}.${appetiteNote}`], clarification_question: null };
  }
  const clarification_question = context.contextual_rejection
    ? '¿Qué alimentos tienes disponibles ahora?'
    : '¿Qué alimentos tienes disponibles ahora?';
  if (context.contextual_rejection) return { context, permitted_claims: [`Entiendo, buscamos otra cosa para este momento. ${clarification_question}`], clarification_question };
  if (context.appetite === 'low') return { context, permitted_claims: [`Si tienes poco apetito, empieza con una porción pequeña que aporte proteína. ${clarification_question}`], clarification_question };
  return { context, permitted_claims: [`Para recomendarte algo concreto, ${clarification_question}`], clarification_question };
}
function permitsFirstContactDiscoveryQuestion(context, obligations) {
  return Array.isArray(obligations) && obligations.length === 1 && obligations[0]?.type === 'general_information' && (!Array.isArray(context?.history) || context.history.length === 0) && !String(context?.most_recent_assistant_message || '').trim();
}
function deliveryChannelFact(message) {
  const value = String(message || '').normalize('NFD').replace(/[\u0300-\u036f]/gu, '').toLowerCase();
  if (/\b(?:descarg|instal|bajar)\w*\b/u.test(value)) {
    return 'Dietavity funciona directamente por WhatsApp; no necesitas descargar una app ni entrar a un portal para usarlo.';
  }
  if (/\b(?:este|por este)\s+(?:numero|chat)\b|\baqui\s+(?:mismo|en el chat)\b|\bpor aqui\b/u.test(value)) {
    return 'Sí 😊 Puedes usar Dietavity directamente en este chat de WhatsApp.';
  }
  return 'Dietavity funciona por WhatsApp; no necesitas un portal para usarlo.';
}
const claims = {"general_information":["Dietavity es un asistente de alimentación por WhatsApp para personas que usan GLP-1. Puedes contarme qué has comido, cuánto apetito tienes o qué alimentos tienes disponibles, y te ayudo a decidir qué comer. Puedes probarlo gratis."],"how_it_works":["Por WhatsApp me cuentas tu situación de comida, te doy una recomendación práctica y podemos ajustarla según lo que te funcione. Puedes probarlo gratis."],"price":["Actualmente puedes probar Dietavity gratis. Todavía no hay un precio futuro definido."],"delivery_channel":["Dietavity funciona por WhatsApp; no necesitas un portal para usarlo."],"glp1_scope":["Dietavity ofrece apoyo para decidir qué comer; no vende, entrega ni receta medicamentos GLP-1."],"medical_boundary":["No puedo orientarte sobre cambiar, iniciar o suspender una dosis. Consulta al profesional que te la prescribe."],"purchase_intent":["La prueba gratuita está disponible actualmente por WhatsApp. No necesitas completar una compra para probarla."],"acknowledgement":["¡Con gusto! 😊"],"unsupported":["No tengo información confirmada para afirmar que Dietavity ofrezca eso."]};
const firstContactDiscoveryQuestion = "¿Qué necesitas resolver con tu alimentación ahora?";
const foodDecision = input.obligations.some(obligation => ['food_decision','food_context','recommendation_feedback'].includes(obligation.type)) ? resolveFoodDecision(input.current_message, input.most_recent_assistant_message, input.history) : null;
let foodClaimAssigned = false;
const resolved_obligations = input.obligations.map(obligation => {
  const food = ['food_decision','food_context','recommendation_feedback'].includes(obligation.type);
  const permitted_claims = food && !foodClaimAssigned ? foodDecision.permitted_claims : food ? [] : obligation.type === 'delivery_channel' ? [deliveryChannelFact(input.current_message)] : [...(claims[obligation.type] || claims.unsupported)];
  if (food) foodClaimAssigned = true;
  return { obligation, resolution: obligation.type === 'unsupported' ? 'bounded_unknown' : 'resolved', permitted_claims, ...(food ? { food_context: foodDecision.context } : {}), prohibited_or_boundary_claims: ['obsolete_28_day_offer','portal_access','price_149','four_meal_product','checkout', ...(obligation.type === 'medical_boundary' ? ['medication_management_advice'] : []), ...(obligation.type === 'glp1_scope' ? ['medication_sale_delivery_or_prescription'] : [])], action_authorization: null, ...(obligation.type === 'purchase_intent' ? { checkout_suppressed_reason: 'proposition_test_no_checkout' } : {}) };
});
const checkout_suppressed_reason = resolved_obligations.find(x => x.checkout_suppressed_reason)?.checkout_suppressed_reason || null;
const discovery_question_authorized = permitsFirstContactDiscoveryQuestion(input, input.obligations);
const clarification_question = discovery_question_authorized ? null : foodDecision?.clarification_question || null;
const required_questions = discovery_question_authorized ? [firstContactDiscoveryQuestion] : clarification_question ? [clarification_question] : [];
const permitted_claims = [...resolved_obligations.flatMap(x => x.permitted_claims), ...(discovery_question_authorized ? [firstContactDiscoveryQuestion] : [])];
return [{ json: { ...input, resolved_obligations, permitted_claims, authorized_action: null, checkout_suppressed_reason, conversation_policy: { discovery_question_authorized, food_clarification_authorized: Boolean(clarification_question), clarification_question, required_questions }, pending_action: 'respond', checkout_authorized: false, checkout_authorization_type: null, checkout_question_response: null, strategy: 'direct_rag_v3_response', buyer_signal: input.obligations.some(x => x.type === 'purchase_intent') ? 'purchase_intent' : 'obligation_resolution', topic: input.obligations.map(x => x.type).join(','), goal: null, offer_version: input.offer_version, inbound_message_sid: input.inbound_message_sid, events: [] } }];

const value = $('Build Direct RAG Composition Envelope').item.json; const required = value.resolved_obligations.map(x => x.obligation.id); let parsed;
try { parsed = JSON.parse(String($input.first().json.output || '').replace(/^\x60\x60\x60(?:json)?\s*|\s*\x60\x60\x60$/g, '')); } catch { parsed = null; }
const canonical = text => String(text || '').trim().replace(/\s+/g, ' ').toLocaleLowerCase('es-MX'); const allowed = new Set(value.permitted_claims.map(canonical));
const obsolete = /(?:\$\s*149|149\s*(?:mxn|pesos?)|28\s*d[ií]as|portal(?:\s+dietavity)?|desayuno,?\s*comida,?\s*cena\s+y\s*snack|cuatro\s+comidas|checkout)/iu;
const grounded = parsed && typeof parsed.response === 'string' && !obsolete.test(parsed.response) && (allowed.has(canonical(parsed.response)) || canonical(parsed.response) === canonical(value.permitted_claims.join(' ')));
const questionCount = parsed && typeof parsed.response === 'string' ? (parsed.response.match(/\?/g) || []).length : Infinity;
const requiredQuestions = Array.isArray(value.composition_envelope?.response_policy?.required_questions) ? value.composition_envelope.response_policy.required_questions : [];
const requiredQuestionsPresentOnce = requiredQuestions.every(question => String(parsed?.response || '').split(question).length - 1 === 1);
const valid = grounded && questionCount === requiredQuestions.length && requiredQuestionsPresentOnce && Array.isArray(parsed.covered_obligation_ids) && required.every(id => parsed.covered_obligation_ids.includes(id));
const fallback = value.permitted_claims.join(' ');
const response = valid ? parsed.response.trim() : fallback;
const unsafe = obsolete.test(response) || /\b(?:sube|baja|aumenta|reduce|cambia|ajusta|suspende|inicia)\b.{0,50}\b(?:dosis|medicamento|mg)\b/i.test(response) || /\b(?:quieres comprar|te env[ií]o el enlace|checkout)\b/i.test(response);
const output = unsafe || !response ? fallback || 'No tengo información confirmada para responder eso.' : response;
return [{ json: { ...value, output, final_gate: { cleared: valid && !unsafe, fallback_used: !valid || unsafe, required_obligation_ids: required, obsolete_claims_rejected: obsolete.test(String(parsed?.response || '')) }, next_last_question_type: null, allow_purchase_cta: false, deterministic_reason: 'direct_rag_v3_final_gate' } }];

const chat = $('When Chat Message Received').item.json;
if (chat.action && chat.action !== 'sendMessage') throw new Error('DIRECT_RAG_HARNESS_SEND_MESSAGE_ONLY');
if (typeof chat.chatInput !== 'string' || !chat.chatInput.trim() || chat.chatInput.length > 2000) throw new Error('DIRECT_RAG_HARNESS_TEXT_REQUIRED');
return [{ json: { session_id: "direct-rag-chat-harness:v1:synthetic-dietavity-customer", current_message: chat.chatInput.trim() } }];

const turn = $('Prepare Test Turn').item.json;
const rawHistory = $input.first().json.history;
let rows = Array.isArray(rawHistory) ? rawHistory : [];
if (typeof rawHistory === 'string') { try { rows = JSON.parse(rawHistory); } catch { rows = []; } }
const history = rows.slice(-12).map(row => ({ role: row.role === 'assistant' ? 'assistant' : 'customer', text: String(row.text || '').slice(0, 1000) }));
return [{ json: { contract_version: 'direct-rag-v3-proposition-test', locale: 'es-MX', session_id: turn.session_id, inbound_message_id: null, inbound_message_sid: null, current_message: turn.current_message, history, most_recent_assistant_message: history.filter(row => row.role === 'assistant').at(-1)?.text || '', customer_state: { paid: false }, commercial_state: { purchase_context: false, checkout_suppressed: true }, offer_version: 'glp1-whatsapp-free-test-v3' } }];

const value = $input.first().json;
if (value.authorized_action !== null || value.checkout_authorized !== false || value.pending_action !== 'respond') throw new Error('DIRECT_RAG_HARNESS_EXTERNAL_ACTION_BLOCKED');
return [{ json: value }];

const persisted = $input.first().json;
if (Number(persisted.persisted_turn_messages) !== 2) throw new Error('DIRECT_RAG_HARNESS_TRANSCRIPT_NOT_PERSISTED');
const result = $('Final Direct RAG Customer Response Gate').item.json;
return [{ json: { output: result.output, assistant_response: result.output, test_identity: "direct-rag-chat-harness:v1:synthetic-dietavity-customer", checkout_executed: false, checkout_suppressed_reason: result.checkout_suppressed_reason || null } }];

